command_source:
param([ValidateSet('build','replay')][string]$Action='build',[ValidatePattern('^[a-z0-9-]+$')][string]$Name='early-amd-r1',[ValidateRange(0,8191)][int]$QueryStart=0,[ValidateRange(1,8192)][int]$QueryCount=64,[ValidateRange(1,32)][int]$Batch=8,[switch]$NativeProducts,[switch]$UseTable,[switch]$Baseline,[switch]$UseRcp,[ValidateRange(0,18)][int]$MemoryLayout=0)
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-attention-cell-parallel-integer-20260912'
$seed='D:\projects\AIMA-public-attention-prepared-value-runtime-20260912'
$sha='aa88b02e901d25d85a6fb3675746dfa1785b8fae'
$bundle='D:\projects\attention-cell-parallel-integer-aa88b02.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '9258946f327fefa3a642c205c0108fad915bc57bc3a24b7b1bf6fc3932e96022'){throw 'Bundle fingerprint mismatch'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD
 if($LASTEXITCODE -ne 0){throw 'Bundle fetch failed'}
 & git -C $seed worktree add --detach $repo $sha
 if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source checkout mismatch'}
$build=Join-Path $repo 'build\attention-replay'
$null=New-Item -ItemType Directory -Path $build -Force
$exe=Join-Path $build 'full-attention-capture-replay.exe'
$source=Join-Path $repo 'native\providers\ck_fmha\full_attention_capture_replay.cpp'
$artifacts=@()
$sourceFiles=@($source,(Join-Path $repo 'native\providers\ck_fmha\blackwell_attention.h'))
foreach($directory in @('native\providers\moe_accumulator','native\providers\gdn')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $directory) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
foreach($file in $sourceFiles){$artifacts+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;source_inputs=$artifacts;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model_loaded=$false;inference_acceptance=$false;model='none; native attention replay build';purpose=$Action}
$spec.memory_layout=$MemoryLayout
$env:QRT_CK_SM121_NATIVE_PRODUCTS=if($NativeProducts){'1'}else{'0'}
$spec.native_products=[bool]$NativeProducts
$spec.mantissa_wmma=($MemoryLayout -eq 5)
$spec.integer_wmma=($MemoryLayout -eq 5 -or $MemoryLayout -eq 18)
$spec.native_mma_pv=($MemoryLayout -eq 6 -or $MemoryLayout -eq 7 -or $MemoryLayout -eq 13)
$spec.native_mma_qk=($MemoryLayout -eq 7 -or $MemoryLayout -eq 14)
$spec.selective_exact_pv=($MemoryLayout -eq 13)
$spec.tiled_exact_qk=($MemoryLayout -ge 15 -and $MemoryLayout -le 17)
$spec.cell_parallel_integer_qk=($MemoryLayout -eq 18)
$spec.prepared_value_encoding=($MemoryLayout -eq 17 -or $MemoryLayout -eq 18)
$spec.environment_overrides=@{QRT_CK_SM121_NATIVE_PRODUCTS=$env:QRT_CK_SM121_NATIVE_PRODUCTS}
$spec.ck_provider_commit='cf5da6481b13278212d102b2050bd54180b773dc'
$spec.ck_provider_sha256='b6619750cb9bd397c0f8c3f79cdf0ab96d7f929374e16fa4ad8d0b543b39af78'
$env:QRT_CK_FMHA_SM121_FULL_PREFIX=if($UseRcp){'1'}else{'0'}
$env:QRT_CK_FMHA_SM121_EXP2_TABLE='D:\projects\sm121-exp2-negative-f490940d.bin'
if($UseRcp){
 $rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
 if((Get-FileHash $rcp -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'd2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'){throw 'Reciprocal table changed'}
 $env:QRT_CK_FMHA_SM121_RCP_TABLE=$rcp
 $spec.reciprocal_table=@{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39';capture_sha256='0d5c590a4078c9fe6f6c90186d7cfb4c815b8a38225903e914cb868f9a3a1fe0'}
}else{Remove-Item Env:QRT_CK_FMHA_SM121_RCP_TABLE -ErrorAction SilentlyContinue}
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','--offload-arch=gfx1151',$source,'-lbcrypt','-o',$exe)
 $out=Join-Path $repo 'build\attention-build-r1';$timeout=140
}else{
 $manifest=[IO.File]::ReadAllText((Join-Path $build 'build-provenance.json'))|ConvertFrom-Json
 if($manifest.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $manifest.executable.sha256){throw 'Replay executable provenance mismatch'}
 $input='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1'
 $q=Join-Path $input 'layer3-full-full_attention_q_norm_rope-bf16.bin'
 $k=Join-Path $input 'layer3-full-full_attention_k_norm_rope-bf16.bin'
 $v=Join-Path $input 'layer3-full-full_attention_v_projection-bf16.bin'
 $reference='D:\projects\full-attention-context-gb10-08734309.bin'
 $ck='D:\projects\AIMA-public-replicated-carry-20260911\build\ck\qrt_ck_fmha_sm121.dll'
 $inputs=@(
  @{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'},@{file=$v;sha256='bd95f94c94ea0606c94b6d98548a672e78479bf6df2d7ace08f3797a85907e80'},@{file=$reference;sha256='f3d9b30a1e70f97a5510a0242006e91e0754207bb8e437cdf46d777bfb6fed33'},
  @{file=$ck;sha256='b6619750cb9bd397c0f8c3f79cdf0ab96d7f929374e16fa4ad8d0b543b39af78'}
 )
 foreach($file in $inputs){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Replay input fingerprint mismatch'}}
 $out=Join-Path $repo ('build\attention-'+$Name)
 $table=if($UseTable){'D:\projects\sm121-exp2-negative-f490940d.bin'}else{'-'}
 $baselineFlag=if($Baseline){'1'}else{'0'}
 $spec.executable=$exe
 $spec.arguments=@($q,$k,$v,$reference,$ck,(Join-Path $out 'attention'),'7169',[string]$QueryStart,[string]$QueryCount,[string]$Batch,$table,$baselineFlag,[string]$MemoryLayout)
 $spec.model='D:\models\Qwen3.6-35B-A3B; captured real q7169 layer-3 Q/K/V'
 $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
 $spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146'
 $spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
 $spec.input_files=$inputs
 $spec.reference_host='aitopatom-66c4'
 $spec.reference_capture_sha256='087343091048d50a12977548a24a6f2a0fd3346352bceb42fb160c3cf6a6bd37'
 $spec.reference_oracle_sha256='7fa645e8111932279e71ad20b9a1117b5f5f4f26074fdd43c7b2d274a86ac121'
 $spec.reference_is_compute_input=$false
 $timeout=180
}
$specPath=Join-Path $build ($Action+'-'+$Name+'-spec.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Output exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout | Out-Null
$record=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$record|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($file in @('product.stdout.jsonl','product.stderr.log')){if(Test-Path (Join-Path $out $file)){[IO.File]::ReadAllLines((Join-Path $out $file))|Select-Object -Last 15}}
if($record.reason -ne 'completed' -or ($record.exit_code -ne 0 -and -not ($Action -eq 'replay' -and $record.exit_code -eq 2)) -or -not $record.host_checks_pass){throw 'Native action or host check failed'}
if($Action -eq 'build'){
 $manifest=[ordered]@{repo_commit=$sha;source_inputs=$artifacts;host=[Environment]::MachineName;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($manifest|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}

if($Action -eq 'replay'){
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne $(if($Baseline){2}else{1})){throw 'Missing attention numerical reports'}
 $matched=($reports[-1].elements -eq $QueryCount*4096 -and $reports[-1].bf16_mismatches -eq 0 -and $reports[-1].nonfinite -eq 0)
 $expectedF32='71b486111bd9d21a3f3b09e9aa8966321aaa73df9873395bdb6ebf220ee141f4'
 $rawControl=@();foreach($artifactName in @('attention-ck-f32.bin','attention-blackwell-sm121-exp-rcp-f32.bin')){if(-not (Test-Path (Join-Path $out $artifactName))){continue};$actual=(Get-FileHash (Join-Path $out $artifactName) -Algorithm SHA256).Hash.ToLowerInvariant();$rawControl+=@{file=$artifactName;sha256=$actual;matches_qualified_native=($actual -eq $expectedF32)}}
 $manifest=@(Get-ChildItem $out -File -Filter '*.bin'|Sort-Object Name|ForEach-Object {@{file=$_.Name;bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 [IO.File]::WriteAllText((Join-Path $out 'file-manifest.json'),($manifest|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
 [ordered]@{bf16_reference_match=$matched;native_raw_f32_control=$rawControl;elements=$QueryCount*4096;f32_control_sha256=$expectedF32;reports=$reports}|ConvertTo-Json -Depth 5
}
